#!/usr/bin/env bash
# Writes .env.local (API overrides) and web/.env.local from the running local
# Supabase stack. Real third-party keys stay in .env.
set -euo pipefail
cd "$(dirname "$0")/.."

eval "$(supabase status -o env 2>/dev/null | grep -E '^(API_URL|DB_URL|PUBLISHABLE_KEY|SECRET_KEY)=')"
: "${API_URL:?local supabase is not running (supabase start)}"

cron_secret=$(grep -s '^CRON_SECRET=' .env.local | cut -d= -f2- || true)
cron_secret=${cron_secret:-$(openssl rand -hex 16)}

cat > .env.local <<EOF
# Generated by scripts/local-env.sh — local Supabase overrides. Do not commit.
SUPABASE_URL=$API_URL
SUPABASE_PUBLISHABLE_KEY=$PUBLISHABLE_KEY
SUPABASE_SECRET_KEY=$SECRET_KEY
SUPABASE_JWKS_URL=$API_URL/auth/v1/.well-known/jwks.json
DATABASE_URL=$DB_URL
PUBLIC_API_BASE=http://localhost:8000
PUBLIC_WEB_BASE=http://localhost:3000
WEB_ORIGINS=http://localhost:3000,http://127.0.0.1:3000
CRON_SECRET=$cron_secret
RUN_SCHEDULER=true
DEMO_MERCHANT_EMAIL=demo@hisaabbolo.test
DEMO_MERCHANT_PASSWORD=hisaab-demo-2026
EOF

cat > web/.env.local <<EOF
# Generated by scripts/local-env.sh. Do not commit.
NEXT_PUBLIC_SUPABASE_URL=$API_URL
NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=$PUBLISHABLE_KEY
NEXT_PUBLIC_API_BASE=http://localhost:8000
EOF

echo "wrote .env.local and web/.env.local"
